ruleToc.chapterList:
@js:list=[];
if (baseUrl.match(/id/)){
    p=result.match(/=(\d+)">最后1页/)[1];
    for(i=0; i<=p;i++){
        list.push({
            n:'第'+[i+1]+'页',
            u:baseUrl.replace(/$/, '&yeshu='+i)
        })
    }
} else list.push({
    n:'空',
    u:''
});
